CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE content_signals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key text UNIQUE NOT NULL,source_event_id text NOT NULL,source_type text NOT NULL,title text NOT NULL,body text NOT NULL,source_url text,audience_segment text NOT NULL,evidence_type text NOT NULL CHECK(evidence_type IN('simulated','source_verified')),observed_at timestamptz NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE topics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic_key text UNIQUE NOT NULL,title text NOT NULL,canonical_title text NOT NULL,status text NOT NULL CHECK(status IN('discovered','scored','needs_review','approved','rejected','backlog','planned','published','measured','archived')),score integer CHECK(score BETWEEN 0 AND 100),score_dimensions jsonb NOT NULL DEFAULT '{}',flags jsonb NOT NULL DEFAULT '{}',owner text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE topic_evidence(topic_id uuid NOT NULL REFERENCES topics(id),signal_id uuid NOT NULL REFERENCES content_signals(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(topic_id,signal_id));
CREATE TABLE review_decisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic_id uuid NOT NULL REFERENCES topics(id),decision text NOT NULL CHECK(decision IN('approved','rejected')),actor text NOT NULL,actor_role text NOT NULL CHECK(actor_role='content_reviewer'),note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE content_backlog(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),topic_id uuid UNIQUE NOT NULL REFERENCES topics(id),priority integer NOT NULL,channel text,status text NOT NULL,planned_for timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE performance_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),idempotency_key text UNIQUE NOT NULL,topic_id uuid NOT NULL REFERENCES topics(id),channel text NOT NULL,impressions bigint NOT NULL CHECK(impressions>=0),clicks bigint NOT NULL CHECK(clicks>=0),conversions bigint NOT NULL CHECK(conversions>=0),evidence_type text NOT NULL CHECK(evidence_type IN('simulated','source_verified')),occurred_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(clicks<=impressions),CHECK(conversions<=clicks));
CREATE TABLE delivery_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_id uuid,attempt_number integer NOT NULL,status text NOT NULL,error_code text,next_retry_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(entity_id,attempt_number));
CREATE TABLE dead_letter_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),entity_type text NOT NULL,entity_id uuid,reason text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id bigserial PRIMARY KEY,entity_type text NOT NULL,entity_id uuid,actor text NOT NULL,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_signals_type_time ON content_signals(source_type,observed_at DESC);CREATE INDEX idx_topics_queue ON topics(status,score DESC);CREATE INDEX idx_performance_topic ON performance_events(topic_id,occurred_at DESC);
